with base as (select *, date_format(signup_date, 'yyyy-MM-dd') as signup_date_label from customers where signup_date >= date '2023-07-20') select country, count_if(country = 'JP') as jp_events, bit_or(age) as age_bit_or, count(case when country = 'US' then 1 end) as us_count, bit_and(age) as age_bit_and, sort_array(collect_set(segment)) as segment_list from base group by country having age_bit_or >= 1 order by country desc nulls first
